referenceSolutionTemplate:
#include <stdio.h>
#include <time.h>

int main(void) {
    time_t fixed = {sec}L;          /* 那一刻的秒数，已经给你了 */
    struct tm *t = gmtime(&fixed);  /* 换成写着年月日的那张牌子 */

    printf("那个数换成日子是：%d-%02d-%02d，一年里的第 %d 天\n",
           t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_yday + 1);
    return 0;
}
